/**
 * Centred layout with no sidebar. It sits beside `(app)`, not inside it,
 * so the shell's redirect to onboarding never wraps this route. If you
 * move it under `(app)`, skip that redirect on this route.
 */

import type { ReactNode } from "react";

export default function OnboardingLayout({
  children,
}: {
  children: ReactNode;
}) {
  return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-background px-4 py-12">
      {children}
    </div>
  );
}

/**
 * Renders the wizard at the caller's persisted step. A caller who has
 * completed onboarding is redirected to the completion screen's target.
 */

// Session reads make this page inherently per-request; declaring it
// dynamic keeps `next build` from attempting a static prerender.
export const dynamic = "force-dynamic";

import { getLocale } from "next-intl/server";
import { redirect } from "@/i18n/navigation";
import { onboarding } from "@/lib/onboarding";
import { onboardingConfig } from "@/lib/onboarding-steps";
import { OnboardingWizard } from "@/components/onboarding/onboarding-wizard";

export default async function OnboardingPage() {
  const state = await onboarding.getState();

  if (state.completed) {
    redirect({
      href: onboardingConfig.complete.ctaHref,
      locale: await getLocale(),
    });
  }

  return <OnboardingWizard initialStepId={state.currentStep} />;
}

"use client";

/**
 * Runs the steps from `@/lib/onboarding-steps`: progress, back/next/skip
 * and the completion screen.
 *
 * It resumes at `initialStepId`, the persisted step. The completion
 * screen persists no step id, so a caller who leaves there resumes at
 * the last answered step. Focus moves to the card on every step change
 * so screen readers announce the new step.
 */

import { useRef, useState, useTransition } from "react";
import { useTranslations } from "next-intl";
import { CheckCircle2 } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";

import { useRouter } from "@/i18n/navigation";
import { EASE_IN_OUT, EASE_OUT } from "@/components/ui/ai-motion";
import { Button } from "@/components/ui/button";
import {
  advanceStep,
  completeOnboarding,
  skipOnboarding,
} from "@/actions/onboarding";
import {
  onboardingConfig,
  type OnboardingAnswers,
} from "@/lib/onboarding-steps";
import { OnboardingStep } from "./onboarding-step";

interface OnboardingWizardProps {
  initialStepId: string | null;
}

export function OnboardingWizard({ initialStepId }: OnboardingWizardProps) {
  const t = useTranslations("onboarding");
  // Namespace-less: completion-screen copy keys are fully qualified
  // (see `@/lib/onboarding-steps`).
  const tAny = useTranslations();
  const router = useRouter();
  const { steps, complete } = onboardingConfig;

  const initialIndex = initialStepId
    ? Math.max(
        steps.findIndex((step) => step.id === initialStepId),
        0
      )
    : 0;

  const [stepIndex, setStepIndex] = useState(initialIndex);
  // Which way the last move went: a step slides in from the side it
  // came from, and the one it replaces leaves the other way.
  const [direction, setDirection] = useState<1 | -1>(1);
  const reduced = useReducedMotion() ?? false;
  const [answers, setAnswers] = useState<OnboardingAnswers>({});
  const [error, setError] = useState<string | null>(null);
  const [isSkipping, startSkip] = useTransition();
  const [isPending, startTransition] = useTransition();
  const cardRef = useRef<HTMLDivElement>(null);

  const isCompleteScreen = stepIndex >= steps.length;
  const currentStep = steps[stepIndex];
  const totalScreens = steps.length + 1; // + the completion screen
  const progressPosition = Math.min(stepIndex, steps.length);

  function focusCard() {
    cardRef.current?.focus();
  }

  function handleAnswerChange(fieldId: string, value: string) {
    setAnswers((prev) => ({ ...prev, [fieldId]: value }));
  }

  function handleNext() {
    if (!currentStep) return;
    setError(null);
    startTransition(async () => {
      const nextIndex = stepIndex + 1;
      const nextStep = steps[nextIndex];
      // The completion screen is not a step and persists no step id.
      const result = nextStep
        ? await advanceStep(nextStep.id, answers)
        : { success: true as const, data: undefined };
      if (!result.success) {
        setError(result.error);
        return;
      }
      setDirection(1);
      setStepIndex(nextIndex);
      focusCard();
    });
  }

  function handleBack() {
    if (stepIndex === 0) return;
    setError(null);
    startTransition(async () => {
      const prevIndex = stepIndex - 1;
      const prevStep = steps[prevIndex];
      if (prevStep) {
        const result = await advanceStep(prevStep.id, answers);
        if (!result.success) {
          setError(result.error);
          return;
        }
      }
      setDirection(-1);
      setStepIndex(prevIndex);
      focusCard();
    });
  }

  function handleSkip() {
    setError(null);
    startSkip(async () => {
      const result = await skipOnboarding();
      if (!result.success) {
        setError(result.error);
        return;
      }
      router.push(complete.ctaHref);
      router.refresh();
    });
  }

  function handleComplete() {
    setError(null);
    startTransition(async () => {
      const result = await completeOnboarding();
      if (!result.success) {
        setError(result.error);
        return;
      }
      router.push(complete.ctaHref);
      router.refresh();
    });
  }

  return (
    <div className="w-full max-w-md">
      <div className="flex justify-end mb-4">
        <Button
          type="button"
          variant="ghost"
          size="sm"
          onClick={handleSkip}
          disabled={isSkipping}
          className="text-muted-foreground"
        >
          {isSkipping ? t("wizard.skipping") : t("wizard.skip")}
        </Button>
      </div>

      <div
        className="flex items-center justify-center gap-2 mb-8"
        role="progressbar"
        aria-valuenow={progressPosition + 1}
        aria-valuemin={1}
        aria-valuemax={totalScreens}
        aria-label={t("wizard.progressLabel")}
      >
        {Array.from({ length: totalScreens }).map((_, index) => (
          <div
            key={index}
            className={`h-1.5 rounded-full transition-[width,background-color] duration-slow ease-emphasized ${
              index === progressPosition
                ? "w-8 bg-primary"
                : index < progressPosition
                  ? "w-1.5 bg-primary/60"
                  : "w-1.5 bg-border"
            }`}
          />
        ))}
      </div>

      <div
        ref={cardRef}
        tabIndex={-1}
        className="rounded-xl border bg-card p-8 outline-none"
      >
        {error && (
          <p role="alert" className="text-sm text-destructive mb-4">
            {error}
          </p>
        )}

        <AnimatePresence mode="wait" initial={false} custom={direction}>
          <motion.div
            key={isCompleteScreen ? "complete" : (currentStep?.id ?? "none")}
            custom={direction}
            variants={{
              enter: (dir: number) =>
                reduced
                  ? { opacity: 0 }
                  : { opacity: 0, x: dir * 24, filter: "blur(3px)" },
              center: {
                opacity: 1,
                x: 0,
                filter: "blur(0px)",
                transition: { duration: reduced ? 0 : 0.32, ease: EASE_OUT },
              },
              leave: (dir: number) =>
                reduced
                  ? { opacity: 0, transition: { duration: 0 } }
                  : {
                      opacity: 0,
                      x: dir * -24,
                      filter: "blur(3px)",
                      transition: { duration: 0.16, ease: EASE_IN_OUT },
                    },
            }}
            initial="enter"
            animate="center"
            exit="leave"
          >
            {isCompleteScreen ? (
              <div className="text-center py-2">
                <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-primary/10 mb-6">
                  <CheckCircle2
                    className="w-8 h-8 text-primary"
                    aria-hidden="true"
                  />
                </div>
                <h2 className="text-xl font-semibold mb-2">
                  {tAny(complete.titleKey)}
                </h2>
                {complete.descriptionKey && (
                  <p className="text-sm text-muted-foreground mb-8">
                    {tAny(complete.descriptionKey)}
                  </p>
                )}
                <Button
                  type="button"
                  className="w-full"
                  onClick={handleComplete}
                  disabled={isPending}
                >
                  {isPending
                    ? t("wizard.finishing")
                    : tAny(complete.ctaLabelKey)}
                </Button>
              </div>
            ) : currentStep ? (
              <OnboardingStep
                step={currentStep}
                answers={answers}
                onAnswerChange={handleAnswerChange}
                onBack={stepIndex > 0 ? handleBack : undefined}
                onNext={handleNext}
                isSubmitting={isPending}
              />
            ) : null}
          </motion.div>
        </AnimatePresence>
      </div>
    </div>
  );
}

"use client";

/**
 * Renders one step's fields from its config in `@/lib/onboarding-steps`:
 * a text input or a single-select card group. For other field types,
 * write your own step component and render it from the wizard.
 */

import { useId } from "react";
import { useTranslations } from "next-intl";
import { CheckCircle2 } from "lucide-react";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import type {
  OnboardingAnswers,
  OnboardingStepConfig,
} from "@/lib/onboarding-steps";

interface OnboardingStepProps {
  step: OnboardingStepConfig;
  answers: OnboardingAnswers;
  onAnswerChange: (fieldId: string, value: string) => void;
  onBack?: () => void;
  onNext: () => void;
  isSubmitting: boolean;
}

function isStepComplete(
  step: OnboardingStepConfig,
  answers: OnboardingAnswers
): boolean {
  return (step.fields ?? []).every((field) => {
    if (!field.required) return true;
    return Boolean(answers[field.id]?.trim());
  });
}

export function OnboardingStep({
  step,
  answers,
  onAnswerChange,
  onBack,
  onNext,
  isSubmitting,
}: OnboardingStepProps) {
  const t = useTranslations("onboarding");
  // Namespace-less: step and field keys are fully qualified, so a step
  // can point at any namespace.
  const tAny = useTranslations();
  const headingId = useId();
  const canProceed = isStepComplete(step, answers);

  return (
    <div role="group" aria-labelledby={headingId}>
      <h2 id={headingId} className="text-xl font-semibold text-center mb-2">
        {tAny(step.titleKey)}
      </h2>
      {step.descriptionKey && (
        <p className="text-sm text-muted-foreground text-center mb-6">
          {tAny(step.descriptionKey)}
        </p>
      )}

      <div className="space-y-5">
        {(step.fields ?? []).map((field) => (
          <div key={field.id} className="space-y-2">
            <Label htmlFor={field.id}>{tAny(field.labelKey)}</Label>

            {field.type === "text" ? (
              <Input
                id={field.id}
                value={answers[field.id] ?? ""}
                onChange={(event) =>
                  onAnswerChange(field.id, event.target.value)
                }
                placeholder={
                  field.placeholderKey ? tAny(field.placeholderKey) : undefined
                }
                required={field.required}
              />
            ) : (
              <div
                className="space-y-2"
                role="radiogroup"
                aria-labelledby={field.id}
              >
                {(field.options ?? []).map((option) => {
                  const selected = answers[field.id] === option.value;
                  return (
                    <button
                      key={option.value}
                      type="button"
                      role="radio"
                      aria-checked={selected}
                      onClick={() => onAnswerChange(field.id, option.value)}
                      className={`w-full flex items-center gap-3 rounded-lg border px-4 py-3 text-left transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 ${
                        selected
                          ? "border-primary bg-primary/5"
                          : "border-border hover:bg-muted"
                      }`}
                    >
                      <div className="flex-1">
                        <p className="text-sm font-medium">
                          {tAny(option.labelKey)}
                        </p>
                        {option.descriptionKey && (
                          <p className="text-xs text-muted-foreground">
                            {tAny(option.descriptionKey)}
                          </p>
                        )}
                      </div>
                      {selected && (
                        <CheckCircle2
                          className="size-5 shrink-0 text-primary"
                          aria-hidden="true"
                        />
                      )}
                    </button>
                  );
                })}
              </div>
            )}
          </div>
        ))}
      </div>

      <div className="flex gap-3 mt-8">
        {onBack && (
          <Button
            type="button"
            variant="outline"
            onClick={onBack}
            disabled={isSubmitting}
          >
            {t("step.back")}
          </Button>
        )}
        <Button
          type="button"
          className="flex-1"
          onClick={onNext}
          disabled={!canProceed || isSubmitting}
        >
          {isSubmitting ? t("step.saving") : t("step.continue")}
        </Button>
      </div>
    </div>
  );
}

"use server";

/**
 * Onboarding actions over the service in `@/lib/onboarding`: call it, map
 * an `OnboardingServiceError` to a translated message, revalidate. The
 * page reads state from the service directly.
 */

import { revalidatePath } from "next/cache";
import { getTranslations } from "next-intl/server";

import { isOnboardingServiceError } from "@intelligo-dev/auth";

import { profile } from "@/lib/onboarding-profile";
import { onboarding } from "@/lib/onboarding";
import {
  onboardingConfig,
  type OnboardingAnswers,
} from "@/lib/onboarding-steps";

export type OnboardingActionResult<T = undefined> =
  { success: true; data: T } | { success: false; error: string };

async function friendlyError(error: unknown): Promise<string> {
  if (isOnboardingServiceError(error)) {
    if (error.code === "invalid_input") return error.message;
    const t = await getTranslations("onboarding");
    if (error.code === "forbidden") return t("errors.forbidden");
    return t("errors.unexpected");
  }
  if (error instanceof Error) return error.message;
  const t = await getTranslations("onboarding");
  return t("errors.generic");
}

/**
 * Moves to `stepId`. First runs `onStepSubmit` from
 * `lib/onboarding-steps.ts` with the answers of the step being left.
 */
export async function advanceStep(
  stepId: string,
  answers: OnboardingAnswers
): Promise<OnboardingActionResult> {
  try {
    if (onboardingConfig.onStepSubmit) {
      await onboardingConfig.onStepSubmit(stepId, answers);
    }
    await onboarding.setStep(stepId);
    return { success: true, data: undefined };
  } catch (error) {
    return { success: false, error: await friendlyError(error) };
  }
}

export async function completeOnboarding(): Promise<OnboardingActionResult> {
  try {
    await onboarding.complete();
    revalidatePath("/");
    return { success: true, data: undefined };
  } catch (error) {
    return { success: false, error: await friendlyError(error) };
  }
}

export async function skipOnboarding(): Promise<OnboardingActionResult> {
  try {
    await onboarding.skip();
    revalidatePath("/");
    return { success: true, data: undefined };
  } catch (error) {
    return { success: false, error: await friendlyError(error) };
  }
}

/**
 * Saves a display name typed into the wizard.
 *
 * A server action because `lib/onboarding-steps.ts` is also imported by
 * the client wizard, and calling a server-only service from there would
 * pull `next/headers` into the client bundle. Any persistence you add in
 * `onStepSubmit` should take the same shape.
 */
export async function saveDisplayName(
  name: string
): Promise<OnboardingActionResult> {
  const trimmed = name.trim();
  // The service validates length; anything shorter is the wizard's own
  // required-field problem, not a reason to fail the step.
  if (trimmed.length < 2) return { success: true, data: undefined };

  try {
    await profile.updateProfile({ name: trimmed });
    return { success: true, data: undefined };
  } catch (error) {
    return { success: false, error: await friendlyError(error) };
  }
}

import "server-only";

/**
 * The onboarding service; it takes no ports. `complete()` and `skip()`
 * provision nothing: first-workspace provisioning belongs in
 * `lib/workspace-bootstrap.ts`.
 */

import { createOnboardingService } from "@intelligo-dev/auth";

export const onboarding = createOnboardingService();

/**
 * The onboarding wizard: its steps, their fields, the completion screen
 * and `onStepSubmit`.
 *
 * Copy is referenced by fully-qualified message key (`titleKey`,
 * `labelKey`, `ctaLabelKey`…), resolved through a namespace-less
 * `useTranslations()`; a step you add can point at any namespace.
 *
 * The framework persists only which step the caller is on. Field
 * answers are kept only if `onStepSubmit` saves them; it runs
 * server-side each time the wizard advances past a step, and by default
 * writes `displayName` to the profile.
 *
 * The client wizard imports this file too, so it must stay client-safe:
 * persist through a server action, never a service imported here.
 */

import { saveDisplayName } from "@/actions/onboarding";

export type OnboardingFieldType = "text" | "select-cards";

export interface OnboardingSelectOption {
  value: string;
  labelKey: string;
  descriptionKey?: string;
}

export interface OnboardingField {
  /** Unique within its step. Used as the answers-map key. */
  id: string;
  type: OnboardingFieldType;
  labelKey: string;
  /** `type: "text"` only. */
  placeholderKey?: string;
  required?: boolean;
  /** `type: "select-cards"` only. */
  options?: OnboardingSelectOption[];
}

export interface OnboardingStepConfig {
  /** Persisted verbatim; at most 64 characters, unique across `steps`. */
  id: string;
  titleKey: string;
  descriptionKey?: string;
  /** Omit for a purely informational step with only a Continue button. */
  fields?: OnboardingField[];
}

export interface OnboardingCompleteConfig {
  titleKey: string;
  descriptionKey?: string;
  ctaLabelKey: string;
  /** Where the completion screen's CTA (and Skip) send the caller. */
  ctaHref: string;
}

export type OnboardingAnswers = Record<string, string>;

export interface OnboardingConfig {
  steps: OnboardingStepConfig[];
  complete: OnboardingCompleteConfig;
  /**
   * Runs server-side whenever the wizard advances past `stepId`, with
   * that step's answers. The only place answers are saved.
   */
  onStepSubmit?: (
    stepId: string,
    answers: OnboardingAnswers
  ) => Promise<void> | void;
}

export const onboardingConfig: OnboardingConfig = {
  steps: [
    {
      id: "purpose",
      titleKey: "onboarding.steps.purpose.title",
      descriptionKey: "onboarding.steps.purpose.description",
      fields: [
        {
          id: "purpose",
          type: "select-cards",
          labelKey: "onboarding.steps.purpose.label",
          required: true,
          options: [
            {
              value: "personal",
              labelKey: "onboarding.steps.purpose.options.personal.label",
              descriptionKey:
                "onboarding.steps.purpose.options.personal.description",
            },
            {
              value: "team",
              labelKey: "onboarding.steps.purpose.options.team.label",
              descriptionKey:
                "onboarding.steps.purpose.options.team.description",
            },
            {
              value: "clients",
              labelKey: "onboarding.steps.purpose.options.clients.label",
              descriptionKey:
                "onboarding.steps.purpose.options.clients.description",
            },
          ],
        },
      ],
    },
    {
      id: "profile",
      titleKey: "onboarding.steps.profile.title",
      descriptionKey: "onboarding.steps.profile.description",
      fields: [
        {
          id: "displayName",
          type: "text",
          labelKey: "onboarding.steps.profile.label",
          placeholderKey: "onboarding.steps.profile.placeholder",
          required: true,
        },
      ],
    },
  ],
  complete: {
    titleKey: "onboarding.complete.title",
    descriptionKey: "onboarding.complete.description",
    ctaLabelKey: "onboarding.complete.cta",
    ctaHref: "/dashboard",
  },
  onStepSubmit: async (stepId, answers) => {
    if (stepId === "profile" && answers.displayName) {
      await saveDisplayName(answers.displayName);
    }
  },
};

